export function workedExample(g,url){
 const r=calculateTotalCost(g.example,24);
 return `<section class="info-note"><h2>이 글의 조건으로 계산한 24개월 비용</h2><dl><dt>기간 내 실제 지출</dt><dd><strong>${money(r.cash)}</strong></dd><dt>기간 종료 후 남은 원금</dt><dd>${money(r.remaining)}</dd><dt>비교 총비용</dt><dd><strong>${money(r.total)}</strong></dd><dt>월평균 부담</dt><dd>${money(r.average)}</dd></dl><p>실제 판매상품이 아닌 설명용 예시입니다. 총비용은 기간 내 지출 + 남은 원금이며 미래 이자는 별도입니다.</p><a class="button primary" href="${url('/calculator')}#q=${encodeQuote(g.example,24)}">예시 조건 불러와 내 견적으로 수정 →</a></section>`;
}
